class TestQKDGatewayIntegration:
    """Integration tests for the QKD gateway key lifecycle and session management."""

    def test_gateway_initialization(self, qkd_gateway):
        """Gateway must initialize with empty key store and no active sessions."""
        assert qkd_gateway is not None
