    def test_generate_keypair(self, qkd_gateway):
        """Gateway must generate and store a keypair."""
        key_id = qkd_gateway.generate_keypair()
        assert key_id is not None
        assert key_id in qkd_gateway.get_key_store()

    def test_generate_keypair_metadata(self, qkd_gateway):
        """Generated keypair must have correct metadata (timestamps, sizes)."""
        key_id = qkd_gateway.generate_keypair()
        meta = qkd_gateway.get_key_metadata(key_id)
        assert meta['public_key_size'] == KYBER_PUBLIC_KEY_SIZE
        assert meta['private_key_size'] == KYBER_SECRET_KEY_SIZE
        assert 'created_at' in meta
        assert isinstance(meta['created_at'], datetime)

    def test_establish_session(self, qkd_gateway):
        """Gateway must establish a session and derive a shared secret."""
        key_id = qkd_gateway.generate_keypair()
        session_id = qkd_gateway.establish_session(key_id)
        assert session_id is not None
        assert session_id in qkd_gateway.get_active_sessions()

    def test_session_shared_secret(self, qkd_gateway):
        """Session must expose a shared secret of correct size."""
        key_id = qkd_gateway.generate_keypair()
        session_id = qkd_gateway.establish_session(key_id)
        ss = qkd_gateway.get_session_shared_secret(session_id)
        assert len(ss) == KYBER_SHARED_SECRET_SIZE

    def test_session_termination(self, qkd_gateway):
        """Terminating a session must remove it from active sessions."""
        key_id = qkd_gateway.generate_keypair()
        session_id = qkd_gateway.establish_session(key_id)
        qkd_gateway.terminate_session(session_id)
        assert session_id not in qkd_gateway.get_active_sessions()

    def test_key_rotation(self, qkd_gateway):
        """Key rotation must invalidate old keys and generate new ones."""
        old_key_id = qkd_gateway.generate_keypair()
        new_key_id = qkd_gateway.rotate_key(old_key_id)
        assert new_key_id != old_key_id
        assert old_key_id not in qkd_gateway.get_key_store()
        assert new_key_id in qkd_gateway.get_key_store()

    def test_full_key_lifecycle(self, qkd_gateway):
        """End-to-end: generate → establish → use → rotate → terminate."""
        key_id = qkd_gateway.generate_keypair()
        session_id = qkd_gateway.establish_session(key_id)
        ss1 = qkd_gateway.get_session_shared_secret(session_id)

        # Rotate key
        new_key_id = qkd_gateway.rotate_key(key_id)
        assert new_key_id != key_id

        # Establish new session with rotated key
        new_session_id = qkd_gateway.establish_session(new_key_id)
        ss2 = qkd_gateway.get_session_shared_secret(new_session_id)
        assert ss1 != ss2  # Different keys → different secrets

        # Terminate both sessions
        qkd_gateway.terminate_session(session_id)
        qkd_gateway.terminate_session(new_session_id)
        assert len(qkd_gateway.get_active_sessions()) == 0


